registerDetail({
  long:
    "Computational Reactor Physics develops the numerical methods used to predict the neutron distribution, power shape, and reactivity of a nuclear reactor with the accuracy demanded by design and licensing. " +
    "The course begins with the neutron diffusion equation and its discretization by finite-difference and modern nodal methods that solve full-core problems efficiently. " +
    "Because cross sections vary sharply with energy, multigroup data are generated by lattice-physics calculations that homogenize fuel assemblies and collapse energy detail. " +
    "Resonance self-shielding is treated so that captures in fertile and absorbing nuclides are represented correctly. " +
    "For high-fidelity transport the method of characteristics tracks neutrons along ray paths through explicit geometry. " +
    "Monte Carlo criticality calculations provide reference solutions by simulating neutron histories, and variance reduction techniques make deep-penetration and shielding problems tractable. " +
    "Coupled neutronics and thermal-hydraulics feedback, together with burnup and depletion calculations that follow isotopic evolution, capture how a core changes over a fuel cycle. " +
    "The course closes with the reactor core simulators that integrate these pieces for operational and safety analysis.",
  topics: [
    "The neutron diffusion equation and boundary conditions",
    "Finite-difference discretization and the eigenvalue problem",
    "Nodal methods for full-core calculations",
    "Multigroup cross-section generation and energy collapsing",
    "Lattice physics and assembly homogenization",
    "Resonance self-shielding and the equivalence theory",
    "The method of characteristics for neutron transport",
    "Discrete ordinates and spherical-harmonics methods",
    "Monte Carlo criticality (k-eigenvalue) calculations",
    "Variance reduction and importance sampling",
    "Coupled neutronics and thermal-hydraulics feedback",
    "Burnup and depletion (Bateman) equations",
    "Fuel cycle and isotopic evolution",
    "Power iteration and acceleration schemes",
    "Reactor core simulators and validation",
  ],
  recommended: [
    res("Computational Methods of Neutron Transport", "E. E. Lewis and W. F. Miller", { type: "textbook" }),
    res("Nuclear Reactor Physics", "Weston M. Stacey", { type: "textbook" }),
  ],
  supplementary: [
    res("Nuclear Reactor Analysis", "James J. Duderstadt and Louis J. Hamilton", { type: "textbook" }),
    res("Nuclear Computational Science: A Century in Review", "Yousry Azmy and Enrico Sartori", { type: "reference" }),
  ],
});
